    delegate bool AccountMoveValidator(long id,long? parent,out string reason);
    void InstallAccountDragging(DataGrid table,Guid scope,AccountMoveValidator valid,Func<long,long,bool> sameType,Action<long,long?> move,Action refresh,TextBlock hint)
    {
        Point start=default;long? dragging=null;DataGridRow? highlighted=null;DateTime lastScroll=DateTime.MinValue,hoverSince=DateTime.MinValue;long? hover=null;
        void Clear(){highlighted?.ClearValue(Control.BackgroundProperty);highlighted?.ClearValue(Control.BorderBrushProperty);highlighted?.ClearValue(Control.BorderThicknessProperty);highlighted=null;}
        AccountDrag? Read(IDataObject data){if(!data.GetDataPresent(AccountDragFormat)||data.GetData(AccountDragFormat) is not string payload)return null;var parts=payload.Split('|');return parts.Length==2&&Guid.TryParse(parts[0],out var origin)&&origin==scope&&long.TryParse(parts[1],out long id)?new(origin,id):null;}
        table.PreviewMouseLeftButtonDown+=(s,e)=>{dragging=null;var handle=Ancestor<Button>(e.OriginalSource as DependencyObject);if(handle?.Name!="AccountDragHandle"||handle.DataContext is not DataRowView row)return;start=e.GetPosition(table);dragging=(long)row["id"];};
        table.PreviewMouseMove+=(s,e)=>{if(e.LeftButton!=MouseButtonState.Pressed){dragging=null;return;}if(dragging is not long id)return;var point=e.GetPosition(table);if(Math.Abs(point.X-start.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(point.Y-start.Y)<SystemParameters.MinimumVerticalDragDistance)return;dragging=null;try{DragDrop.DoDragDrop(table,new DataObject(AccountDragFormat,scope.ToString("N")+"|"+id),DragDropEffects.Move);}finally{Clear();hover=null;}};
        // A type heading (negative id) means "top level"; any other row is the new parent.
        bool Target(DragEventArgs e,out AccountDrag? drag,out DataGridRow? row,out long? parent,out string reason)
        {
            drag=Read(e.Data);row=Ancestor<DataGridRow>(e.OriginalSource as DependencyObject);parent=null;reason="";
            if(drag==null||row?.Item is not DataRowView value)return false;long target=(long)value["id"];parent=target<0?null:target;
            if(target<0&&!sameType(drag.Id,target)){reason=T("هذا العنوان لنوع حساب آخر","That heading is for a different account type");return false;}
            return valid(drag.Id,parent,out reason);
        }
        void Over(DragEventArgs e)
        {
            Clear();e.Effects=DragDropEffects.None;e.Handled=true;
            if((DateTime.UtcNow-lastScroll).TotalMilliseconds>100){var point=e.GetPosition(table);var scroll=Descendants<ScrollViewer>(table).FirstOrDefault();if(point.Y<70)scroll?.LineUp();else if(point.Y>table.ActualHeight-40)scroll?.LineDown();lastScroll=DateTime.UtcNow;}
            if(!Target(e,out var drag,out var row,out var parent,out string reason)){if(drag!=null&&row!=null&&reason.Length>0)hint.Text=reason;return;}
            e.Effects=DragDropEffects.Move;hint.Text=parent==null?T("اتركه هنا ليصبح حسابًا رئيسيًا","Drop here to make a main account"):T("اتركه هنا ليصبح فرعًا للحساب","Drop here to make a child account");
            long target=(long)((DataRowView)row!.Item)["id"];highlighted=row;row.Background=UiTheme.Brush(Resources,"Brush.Sunken");row.BorderBrush=accent;row.BorderThickness=new Thickness(0,1,0,1);
            if(hover!=target){hover=target;hoverSince=DateTime.UtcNow;}else if(collapsedAccountGroups.Contains(target)&&(DateTime.UtcNow-hoverSince).TotalMilliseconds>650){collapsedAccountGroups.Remove(target);refresh();hoverSince=DateTime.UtcNow;}
        }
        void Drop(DragEventArgs e){Clear();e.Handled=true;if(!Target(e,out var drag,out _,out var parent,out _)||drag==null)return;Guard(()=>move(drag.Id,parent));}
        table.DragOver+=(s,e)=>Over(e);table.Drop+=(s,e)=>Drop(e);table.DragLeave+=(s,e)=>{Clear();hover=null;};
    }
